function defaultSettings(){return {
  unit:'cm', grid:true, snap:true, snapSize:10, wallSnap:true, objectSnap:true,
  labels:true, dimensions:true, clearances:true, zones:true, measurements:true,
  fixtures:true, furniture:true, haptics:true, reduceMotion:false, confirmDelete:true,
  performanceMode:'auto', theme:'pink', workspaceMode:'plan',
  autoFitOnOpen:true, showFitStatus:true, showIssueStatus:true, startupView:'rooms'
}}
function newLayout(name='Layout A', objects=[]){return {id:uid('layout'),name,objects,measurements:[],notes:[],createdAt:now(),updatedAt:now(),favorite:false}}
function defaultState(){return {
  version:3, settings:defaultSettings(), rooms:[], library:[], favoritePresetIds:[], recentPresetIds:[], roomTemplates:[],
  currentRoomId:null,currentLayoutId:null,selectedId:null,view:'rooms',zoom:1,
  history:[],future:[],measureDraft:null,activeTool:'select'
}}

let state = loadState();
let roomFilter = 'all';
let drag = null;
let saveTimer = null;
let toastTimer = null;
let resizeTimer = null;
let dragFrame = 0;
let pendingDragTransform = null;
const issueCache = new WeakMap();

function loadState(){
  let raw = null;
  try { raw = JSON.parse(localStorage.getItem(STORAGE_KEY)||'null'); } catch {}
  if(!raw){
    for(const key of LEGACY_KEYS){
      try { raw = JSON.parse(localStorage.getItem(key)||'null'); if(raw) break; } catch {}
    }
  }
  return migrateState(raw);
}
function migrateState(raw){
  const s = defaultState();
  if(!raw || typeof raw!=='object') return s;
  s.settings = Object.assign(defaultSettings(), raw.settings||{});
  s.rooms = Array.isArray(raw.rooms)?raw.rooms:[];
  s.library = Array.isArray(raw.library)?raw.library:[];
  s.favoritePresetIds = Array.isArray(raw.favoritePresetIds)?raw.favoritePresetIds:[];
  s.recentPresetIds = Array.isArray(raw.recentPresetIds)?raw.recentPresetIds:[];
  s.roomTemplates = Array.isArray(raw.roomTemplates)?raw.roomTemplates:[];
  s.currentRoomId = raw.currentRoomId||null; s.currentLayoutId=raw.currentLayoutId||null;
  s.view = s.settings.startupView==='last'&&raw.view==='plan'?'plan':'rooms'; s.zoom=clamp(Number(raw.zoom)||1,.55,2.4);
  const legacyMeasurements = Array.isArray(raw.measurements)?raw.measurements:[];
  s.rooms.forEach((r,ri)=>{
    r.id ||= uid('room'); r.name ||= `Room ${ri+1}`; r.width=Math.max(100,Number(r.width)||350); r.height=Math.max(100,Number(r.height)||420); r.unit=UNIT[r.unit]?r.unit:'cm';
    r.starred=!!r.starred; r.notes ||= ''; r.roomType ||= 'Room'; r.createdAt ||= now(); r.updatedAt ||= now();
    if(!Array.isArray(r.layouts)||!r.layouts.length) r.layouts=[newLayout('Layout A')];
    r.layouts.forEach((l,li)=>{
      l.id ||= uid('layout'); l.name ||= `Layout ${String.fromCharCode(65+li)}`; l.createdAt ||= now(); l.updatedAt ||= now(); l.favorite=!!l.favorite;
      if(!Array.isArray(l.objects)) l.objects=[]; if(!Array.isArray(l.measurements)) l.measurements=(ri===0&&li===0)?legacyMeasurements:[]; if(!Array.isArray(l.notes)) l.notes=[];
      l.objects=l.objects.filter(Boolean).map(normalizeObject);
    });
  });
  if(!s.rooms.some(r=>r.id===s.currentRoomId)){s.currentRoomId=s.rooms[0]?.id||null}
  const r=s.rooms.find(x=>x.id===s.currentRoomId); if(r&&!r.layouts.some(l=>l.id===s.currentLayoutId))s.currentLayoutId=r.layouts[0]?.id||null;
  if(!r) s.view='rooms';
  return s;
}
function normalizeObject(o){
  o.id ||= uid('obj'); o.type ||= 'furniture'; o.name ||= 'Object'; o.x=Number(o.x)||0;o.y=Number(o.y)||0;o.w=Math.max(1,Number(o.w)||50);o.h=Math.max(1,Number(o.h)||50);
  o.rotation=Number(o.rotation)||0;o.color ||= '#eadce0';o.locked=!!o.locked;o.hidden=!!o.hidden;o.clearance=Math.max(0,Number(o.clearance)||0);o.notes ||= '';o.tags=Array.isArray(o.tags)?o.tags:[];
  o.price=Math.max(0,Number(o.price)||0);o.height=Math.max(0,Number(o.height)||0);o.cableLength=Math.max(0,Number(o.cableLength)||0);o.measureConfidence ||= 'exact';o.owned=o.owned!==false;
  return o;
}
function persistentPayload(){
  return {version:3,settings:state.settings,rooms:state.rooms,library:state.library,favoritePresetIds:state.favoritePresetIds,recentPresetIds:state.recentPresetIds,roomTemplates:state.roomTemplates,currentRoomId:state.currentRoomId,currentLayoutId:state.currentLayoutId,view:state.view,zoom:state.zoom};
}
function saveNow(){
  clearTimeout(saveTimer);
  const status=$('#saveStatus'); if(status)status.textContent='Saving…';
  try {localStorage.setItem(STORAGE_KEY,JSON.stringify(persistentPayload()));if(status)status.textContent='Saved'}
  catch(err){if(status)status.textContent='Save failed';toast('Storage is full — export a backup before adding more.')}
}
function markLayoutDirty(layout=currentLayout()){if(layout)issueCache.delete(layout)}
function persist(delay=220){
  markLayoutDirty();const status=$('#saveStatus');if(status)status.textContent='Saving…';clearTimeout(saveTimer);saveTimer=setTimeout(saveNow,delay);
}
function historyPayload(){return JSON.stringify({rooms:state.rooms,library:state.library,currentRoomId:state.currentRoomId,currentLayoutId:state.currentLayoutId})}
function snapshot(){
  if(!currentRoom()&&!state.rooms.length)return;
  state.history.push(historyPayload()); if(state.history.length>MAX_HISTORY)state.history.shift(); state.future=[]; updateUndoRedo();
}
function restoreHistory(json){const p=JSON.parse(json);state.rooms=p.rooms||[];state.library=p.library||[];state.currentRoomId=p.currentRoomId||null;state.currentLayoutId=p.currentLayoutId||null;state.selectedId=null;state.measureDraft=null;}
function undo(){if(!state.history.length)return toast('Nothing to undo');state.future.push(historyPayload());restoreHistory(state.history.pop());persist();renderAll();toast('Undone')}
function redo(){if(!state.future.length)return toast('Nothing to redo');state.history.push(historyPayload());restoreHistory(state.future.pop());persist();renderAll();toast('Redone')}

function currentRoom(){return state.rooms.find(r=>r.id===state.currentRoomId)||null}
function currentLayout(){const r=currentRoom();return r?.layouts.find(l=>l.id===state.currentLayoutId)||r?.layouts[0]||null}
function objects(){return currentLayout()?.objects||[]}
function measurements(){return currentLayout()?.measurements||[]}
function rUnit(){return currentRoom()?.unit||state.settings.unit}
function display(vCm,unit=state.settings.unit){const u=UNIT[unit]||UNIT.cm;const val=Number(vCm||0)/u.toCm;return unit==='cm'?`${Math.round(val)} cm`:unit==='m'?`${Number(val.toFixed(2))} m`:unit==='in'?`${Number(val.toFixed(1))} in`:`${Number(val.toFixed(2))} ft`}
function displayArea(cm2,unit=rUnit()){if(unit==='m')return `${(cm2/10000).toFixed(2)} m²`;if(unit==='ft')return `${(cm2/929.0304).toFixed(1)} ft²`;return `${Math.round(cm2).toLocaleString()} cm²`}
function toCm(value,unit){return Math.max(0,Number(value||0))*(UNIT[unit]?.toCm||1)}
function unitInput(cm,u){return Number((cm/(UNIT[u]?.toCm||1)).toFixed(u==='cm'?0:2))}
function haptic(ms=8){if(state.settings.haptics&&navigator.vibrate)navigator.vibrate(ms)}
function toast(msg){const el=$('#toast');if(!el)return;el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),1900)}
function esc(s=''){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function attr(s=''){return esc(s)}
function slug(s='dango'){return String(s).toLowerCase().trim().replace(/[^a-z0-9]+/g,'-').replace(/(^-|-$)/g,'')||'dango'}
function S(tag,attrs={}){const el=document.createElementNS(SVG_NS,tag);Object.entries(attrs).forEach(([k,v])=>el.setAttribute(k,v));return el}

function modal(title,html,onOpen){
  const tpl=$('#modalTemplate').content.cloneNode(true),root=$('.modal-backdrop',tpl);$('h3',root).textContent=title;$('.modal-body',root).innerHTML=html;$('.modal-close',root).onclick=()=>root.remove();
  root.addEventListener('click',e=>{if(e.target===root)root.remove()});$('#modalRoot').appendChild(root);onOpen?.(root);return root;
}

function createRoom(data){
  const w=toCm(data.width,data.unit),h=toCm(data.height,data.unit);if(!w||!h)return toast('Enter valid room measurements.');snapshot();const layout=newLayout('Layout A');
  const room={id:uid('room'),name:(data.name||'Untitled Room').trim(),width:Math.max(100,w),height:Math.max(100,h),unit:data.unit||'cm',roomType:data.roomType||'Room',starred:false,notes:'',createdAt:now(),updatedAt:now(),layouts:[layout]};
  state.rooms.unshift(room);state.currentRoomId=room.id;state.currentLayoutId=layout.id;state.view='plan';state.zoom=1;state.selectedId=null;persist();renderAll();toast('Room created');
}
function newRoomModal(){
  const u=state.settings.unit;
  const templateHtml=state.roomTemplates.length?`<div class="field full"><label>Saved room templates</label><div class="preset-row">${state.roomTemplates.map(t=>`<button type="button" data-template="${attr(t.id)}">${esc(t.name)}</button>`).join('')}</div></div>`:'';
  modal('Create a room',`<form id="newRoomForm" class="form-grid">
    <div class="field full"><label>Room name</label><input name="name" placeholder="e.g. Bedroom" maxlength="50" autocomplete="off"></div>
    <div class="field"><label>Width</label><input name="width" type="number" inputmode="decimal" min="1" step="0.1" placeholder="Enter width" required></div>
    <div class="field"><label>Length</label><input name="height" type="number" inputmode="decimal" min="1" step="0.1" placeholder="Enter length" required></div>
    <div class="field"><label>Unit</label><select name="unit">${Object.keys(UNIT).map(k=>`<option value="${k}" ${k===u?'selected':''}>${UNIT[k].label}</option>`).join('')}</select></div>
    <div class="field"><label>Room type</label><select name="roomType"><option selected>Room</option><option>Bedroom</option><option>Living room</option><option>Office</option><option>Dining room</option><option>Kitchen</option><option>Studio</option><option>Storage</option><option>Utility</option></select></div>
    <div class="field full"><label>Optional quick sizes</label><div class="preset-row"><button type="button" data-size="300,300">3 × 3 m</button><button type="button" data-size="350,420">3.5 × 4.2 m</button><button type="button" data-size="400,500">4 × 5 m</button><button type="button" data-size="600,350">6 × 3.5 m</button></div></div>
    ${templateHtml}
    <div class="field full"><p class="help">Nothing is pre-added. Start with your real room measurements, then add only the furniture and fixtures you actually need.</p></div>
    <div class="form-actions field full"><button type="button" class="secondary-btn cancel">Cancel</button><button class="primary-btn">Create room</button></div>
  </form>`,m=>{
    const f=$('#newRoomForm',m);$('.cancel',m).onclick=()=>m.remove();
    $$('[data-size]',m).forEach(b=>b.onclick=()=>{const [cw,ch]=b.dataset.size.split(',').map(Number),unit=$('[name="unit"]',f).value;$('[name="width"]',f).value=unitInput(cw,unit);$('[name="height"]',f).value=unitInput(ch,unit)});
    $$('[data-template]',m).forEach(b=>b.onclick=()=>{m.remove();createRoomFromTemplate(b.dataset.template)});
    f.onsubmit=e=>{e.preventDefault();createRoom(Object.fromEntries(new FormData(f)));m.remove()}
  })
}
function renderRooms(){
  const grid=$('#roomsGrid');let rs=state.rooms.filter(r=>roomFilter==='all'||r.starred);$('#roomCountLabel').textContent=`${rs.length} saved room${rs.length===1?'':'s'}`;
  if(!rs.length){grid.innerHTML=`<div class="empty-state"><div class="big">🍡</div><h3>${state.rooms.length?'No starred rooms yet':'Your first layout starts here'}</h3><p>${state.rooms.length?'Star a room to keep it here.':'Add your first measured room. Dango starts empty, so you only add the rooms and items that are actually yours.'}</p>${state.rooms.length?'':'<button class="primary-btn" id="emptyNewBtn">＋ Create room</button>'}</div>`;$('#emptyNewBtn')?.addEventListener('click',newRoomModal);return}
  grid.innerHTML=rs.map(r=>{const l=r.layouts.find(x=>x.id===state.currentLayoutId&&r.id===state.currentRoomId)||r.layouts[0];return `<article class="room-card" data-room="${r.id}"><div class="room-thumb">${miniPlan(r,l)}</div><div><h3>${esc(r.name)}</h3><p>${esc(r.roomType||'Room')} • ${display(r.width,r.unit)} × ${display(r.height,r.unit)}<br>${r.layouts.length} layout${r.layouts.length===1?'':'s'} • ${l?.objects?.length||0} item${l?.objects?.length===1?'':'s'}</p></div><div class="room-actions"><button class="tiny-btn star" aria-label="Star">${r.starred?'⭐':'☆'}</button><button class="tiny-btn menu" aria-label="Room actions">⋮</button></div></article>`}).join('');
  $$('.room-card',grid).forEach(card=>{card.onclick=e=>{if(!e.target.closest('button'))openRoom(card.dataset.room)};$('.star',card).onclick=()=>{const r=state.rooms.find(x=>x.id===card.dataset.room);r.starred=!r.starred;persist();renderRooms()};$('.menu',card).onclick=()=>roomActions(card.dataset.room)})
}
