function addDoor(d){snapshot();const r=currentRoom(),width=Math.max(30,toCm(d.width,rUnit())),off=toCm(d.offset,rUnit());let o=normalizeObject({id:uid('obj'),type:'door',name:'Door',w:width,h:4,rotation:0,color:'#f7a8bd',hinge:d.hinge,swing:d.swing,kind:d.kind||'hinged',wall:d.wall,clearance:width,locked:false});if(d.wall==='top'){o.x=clamp(off,0,r.width-width);o.y=-2}else if(d.wall==='bottom'){o.x=clamp(off,0,r.width-width);o.y=r.height-2}else if(d.wall==='left'){o.w=4;o.h=width;o.x=-2;o.y=clamp(off,0,r.height-width)}else{o.w=4;o.h=width;o.x=r.width-2;o.y=clamp(off,0,r.height-width)}objects().push(o);state.selectedId=o.id;persist();renderPlan(true);toast('Door added')}
