function objectBounds(o){
  const w=Math.max(0,Number(o.w)||0),h=Math.max(0,Number(o.h)||0),cx=(Number(o.x)||0)+w/2,cy=(Number(o.y)||0)+h/2,rad=((Number(o.rotation)||0)%360)*Math.PI/180;
  if(!rad)return{x:Number(o.x)||0,y:Number(o.y)||0,w,h};const c=Math.abs(Math.cos(rad)),sn=Math.abs(Math.sin(rad)),bw=w*c+h*sn,bh=w*sn+h*c;return{x:cx-bw/2,y:cy-bh/2,w:bw,h:bh};
}
function overlap(a,b,pad=0){const A=objectBounds(a),B=objectBounds(b);return A.x-pad<B.x+B.w&&A.x+A.w+pad>B.x&&A.y-pad<B.y+B.h&&A.y+A.h+pad>B.y}
function buildSpatialIndex(items,cell=120){const map=new Map();for(const item of items){const b=objectBounds(item),x0=Math.floor(b.x/cell),x1=Math.floor((b.x+b.w)/cell),y0=Math.floor(b.y/cell),y1=Math.floor((b.y+b.h)/cell);for(let x=x0;x<=x1;x++)for(let y=y0;y<=y1;y++){const k=x+','+y;if(!map.has(k))map.set(k,[]);map.get(k).push(item)}}return{map,cell}}
function querySpatial(index,rect){const b=objectBounds(rect),x0=Math.floor(b.x/index.cell),x1=Math.floor((b.x+b.w)/index.cell),y0=Math.floor(b.y/index.cell),y1=Math.floor((b.y+b.h)/index.cell),out=new Map();for(let x=x0;x<=x1;x++)for(let y=y0;y<=y1;y++)for(const item of index.map.get(x+','+y)||[])out.set(item.id,item);return [...out.values()]}
function spatialPairs(index){const seen=new Set(),pairs=[];for(const bucket of index.map.values())for(let i=0;i<bucket.length;i++)for(let j=i+1;j<bucket.length;j++){const a=bucket[i],b=bucket[j],k=a.id<b.id?a.id+'|'+b.id:b.id+'|'+a.id;if(!seen.has(k)){seen.add(k);pairs.push([a,b])}}return pairs}
function isBlocking(o){return !o.hidden&&!o.nonBlocking&&!['door','window','outlet','switch','drain','router','zone'].includes(o.type)}
function doorClearanceRect(d){const r=currentRoom(),rad=d.clearance||Math.max(d.w,d.h);if(d.wall==='top')return{x:d.x,y:d.swing==='outward'?-rad:0,w:Math.max(d.w,rad),h:rad};if(d.wall==='bottom')return{x:d.x,y:d.swing==='outward'?r.height:r.height-rad,w:Math.max(d.w,rad),h:rad};if(d.wall==='left')return{x:d.swing==='outward'?-rad:0,y:d.y,w:rad,h:Math.max(d.h,rad)};return{x:d.swing==='outward'?r.width:r.width-rad,y:d.y,w:rad,h:Math.max(d.h,rad)}}
function nearestOutletDistance(o,arr=objects()){const outlets=arr.filter(x=>x.type==='outlet'&&!x.hidden);if(!outlets.length)return Infinity;const cx=o.x+o.w/2,cy=o.y+o.h/2;return Math.min(...outlets.map(a=>Math.hypot(cx-(a.x+a.w/2),cy-(a.y+a.h/2))))}
function dedupeIssues(a){const seen=new Set();return a.filter(x=>{const k=x.type+':'+x.ids.slice().sort().join('|');if(seen.has(k))return false;seen.add(k);return true})}
function detectIssues(layout=currentLayout()){
  const r=currentRoom(),arr=layout?.objects||[],issues=[];if(!r)return issues;const outlets=arr.filter(x=>x.type==='outlet'&&!x.hidden),blockers=arr.filter(isBlocking),spatial=buildSpatialIndex(blockers);
  arr.forEach(o=>{if(o.hidden||['door','window','zone'].includes(o.type))return;const b=objectBounds(o);if(b.x<0||b.y<0||b.x+b.w>r.width||b.y+b.h>r.height)issues.push({type:'outside',severity:'high',ids:[o.id],title:`${o.name} extends outside the room`,detail:'Move or resize the item so it stays inside the room.'});if(o.measureConfidence==='remeasure')issues.push({type:'remeasure',severity:'low',ids:[o.id],title:`Re-measure ${o.name}`,detail:'This item is marked as needing a confirmed measurement.'});if(o.cableLength>0&&nearestOutletDistance(o,outlets)>o.cableLength)issues.push({type:'cable',severity:'medium',ids:[o.id],title:`${o.name} may not reach an outlet`,detail:`Nearest outlet is farther than the saved ${display(o.cableLength,rUnit())} cable reach.`})});
  spatialPairs(spatial).forEach(([a,b])=>{if(overlap(a,b))issues.push({type:'overlap',severity:'high',ids:[a.id,b.id],title:`${a.name} overlaps ${b.name}`,detail:'Separate the items or resize one of them.'})});
  arr.filter(d=>d.type==='door'&&d.kind!=='sliding'&&d.kind!=='pocket').forEach(d=>{const zone=doorClearanceRect(d);querySpatial(spatial,zone).forEach(o=>{if(o.id!==d.id&&overlap(zone,o))issues.push({type:'door',severity:'high',ids:[d.id,o.id],title:`Door swing may hit ${o.name}`,detail:'Keep the door-swing area clear.'})})});
  arr.filter(z=>z.type==='zone'&&z.zoneKind==='keepclear'&&!z.hidden).forEach(z=>querySpatial(spatial,z).forEach(o=>{if(overlap(z,o))issues.push({type:'zone',severity:'medium',ids:[z.id,o.id],title:`${o.name} blocks “${z.name}”`,detail:'This zone is marked to stay clear.'})}));
  return dedupeIssues(issues);
}
function issuesModal(){const issues=detectIssues();modal(`Layout issues (${issues.length})`,issues.length?`<div class="list">${issues.map(i=>`<button class="issue-card bad" data-issue="${i.ids.at(-1)}"><b>${i.severity==='high'?'⚠️':i.severity==='medium'?'◼':'○'} ${esc(i.title)}</b><p>${esc(i.detail)}</p></button>`).join('')}</div>`:`<div class="empty-state"><div class="big">✨</div><h3>No conflicts found</h3><p>Dango did not find overlaps, blocked keep-clear zones, outside-room objects, cable-reach issues or door-swing conflicts.</p></div>`,m=>$$('[data-issue]',m).forEach(b=>b.onclick=()=>{state.selectedId=b.dataset.issue;m.remove();renderPlan()}))}

function getIssues(layout=currentLayout()){
  if(!layout)return [];
  const cached=issueCache.get(layout);if(cached)return cached;
  const value=detectIssues(layout);issueCache.set(layout,value);return value;
}
function updatePlanStatus(){
  const l=currentLayout();if(!l)return;const issues=getIssues(l),metrics=layoutMetrics(l);
  const fit=$('#fitStatus'),is=$('#issuesStatus');
  if(fit){fit.textContent=`Fit ${metrics.score}`;fit.classList.toggle('good',metrics.score>=85);fit.classList.toggle('hidden',!state.settings.showFitStatus)}
  if(is){is.textContent=issues.length>999?'999+ issues':`${issues.length} issue${issues.length===1?'':'s'}`;is.classList.toggle('has-issues',issues.length>0);is.classList.toggle('good',issues.length===0);is.classList.toggle('hidden',!state.settings.showIssueStatus)}
}

function layoutMetrics(layout=currentLayout()){
  const r=currentRoom(),obs=(layout?.objects||[]).filter(o=>o.type==='furniture'&&!o.hidden&&!o.nonBlocking),area=r.width*r.height,used=obs.reduce((s,o)=>s+o.w*o.h,0),issues=layout===currentLayout()?getIssues(layout):detectIssues(layout),cost=(layout?.objects||[]).filter(o=>o.owned===false).reduce((s,o)=>s+(o.price||0),0),occupied=Math.min(999,used/area*100),remeasure=(layout?.objects||[]).filter(o=>o.measureConfidence==='remeasure').length;let score=100-issues.filter(i=>i.severity==='high').length*12-issues.filter(i=>i.severity==='medium').length*6-issues.filter(i=>i.severity==='low').length*2;if(occupied>80)score-=Math.round((occupied-80)*1.5);score=clamp(Math.round(score),0,100);return{items:layout?.objects?.length||0,issues:issues.length,occupied,remaining:Math.max(0,area-used),score,cost,remeasure}}
function insightsModal(){const r=currentRoom(),l=currentLayout();if(!r||!l)return toast('Create a room first');const m=layoutMetrics(l),doorWidths=objects().filter(o=>o.type==='door').map(o=>Math.max(o.w,o.h)),maxDoor=doorWidths.length?Math.max(...doorWidths):0;modal('Space insights',`<div class="metrics-grid"><div class="metric-card"><b>${m.score}</b><span>Dango Fit score</span></div><div class="metric-card"><b>${m.occupied.toFixed(1)}%</b><span>Floor footprint</span></div><div class="metric-card"><b>${m.issues}</b><span>Planning issues</span></div><div class="metric-card"><b>${displayArea(m.remaining,r.unit)}</b><span>Approx. free area</span></div></div><div class="list"><button class="list-row" id="fitSelected"><span>✨ Where can selected item fit?</span><span>›</span></button><button class="list-row" id="whatFits"><span>🧩 What fits in a space?</span><span>›</span></button><button class="list-row" id="fitThroughDoor"><span>📦 Will selected item fit through a door?</span><span>${maxDoor?display(maxDoor,r.unit):'No door'}</span></button><button class="list-row" id="compareLayouts"><span>🅰️🅱️ Compare layouts</span><span>›</span></button><button class="list-row" id="shoppingList"><span>🛒 Shopping list</span><span>${objects().filter(o=>o.owned===false).length}</span></button><button class="list-row" id="remeasureList"><span>📐 Re-measure list</span><span>${m.remeasure}</span></button><button class="list-row" id="objectList"><span>🗂 Object list</span><span>${objects().length}</span></button></div><p class="help">The Fit score is a planning aid based on conflicts, clearances and room footprint — not an architectural or safety certification.</p>`,root=>{$('#fitSelected',root).onclick=()=>{root.remove();whereCanFitSelected()};$('#whatFits',root).onclick=()=>{root.remove();whatFitsModal()};$('#fitThroughDoor',root).onclick=()=>fitThroughDoor();$('#compareLayouts',root).onclick=()=>{root.remove();compareLayoutsModal()};$('#shoppingList',root).onclick=()=>{root.remove();shoppingListModal()};$('#remeasureList',root).onclick=()=>{root.remove();remeasureModal()};$('#objectList',root).onclick=()=>{root.remove();objectListModal()}})}
function fitPlacement(o,x,y){const r=currentRoom(),test={...o,x,y},b=objectBounds(test);if(b.x<0||b.y<0||b.x+b.w>r.width||b.y+b.h>r.height)return false;return !objects().some(a=>a.id!==o.id&&isBlocking(a)&&overlap(test,a))&&!objects().some(z=>z.type==='zone'&&z.zoneKind==='keepclear'&&overlap(test,z))}
function findPlacements(o){const r=currentRoom(),pad=10,cands=[[0,0],[r.width-o.w,0],[0,r.height-o.h],[r.width-o.w,r.height-o.h],[r.width/2-o.w/2,0],[r.width/2-o.w/2,r.height-o.h],[0,r.height/2-o.h/2],[r.width-o.w,r.height/2-o.h/2],[r.width/2-o.w/2,r.height/2-o.h/2]];objects().filter(a=>a.id!==o.id&&isBlocking(a)).forEach(a=>{cands.push([a.x+a.w+pad,a.y],[a.x-o.w-pad,a.y],[a.x,a.y+a.h+pad],[a.x,a.y-o.h-pad])});const out=[];for(const [x,y] of cands){const xx=clamp(x,0,r.width-o.w),yy=clamp(y,0,r.height-o.h);if(fitPlacement(o,xx,yy)&&!out.some(p=>Math.abs(p.x-xx)<1&&Math.abs(p.y-yy)<1))out.push({x:xx,y:yy});if(out.length>=8)break}return out}
function whereCanFitSelected(){const o=objects().find(x=>x.id===state.selectedId);if(!o)return toast('Select an object first');const spots=findPlacements(o);modal(`Where can ${o.name} fit?`,spots.length?`<div class="candidate-grid">${spots.map((p,i)=>`<button class="candidate" data-i="${i}"><b>Spot ${i+1}</b><span>${display(p.x,rUnit())} from left<br>${display(p.y,rUnit())} from top</span></button>`).join('')}</div>`:`<div class="empty-state"><div class="big">🧩</div><h3>No simple open spot found</h3><p>Try rotating the item, creating another layout, or reducing nearby clearances.</p></div>`,m=>$$('[data-i]',m).forEach(b=>b.onclick=()=>{const p=spots[Number(b.dataset.i)];snapshot();o.x=p.x;o.y=p.y;persist();m.remove();renderPlan(true);toast('Moved to an open spot')}))}
function whatFitsModal(){const u=rUnit();modal('What fits in this space?',`<form id="fitsForm" class="form-grid"><div class="field"><label>Available width (${u})</label><input name="w" type="number" value="${unitInput(100,u)}"></div><div class="field"><label>Available depth (${u})</label><input name="h" type="number" value="${unitInput(100,u)}"></div><div class="field full"><label>Category</label><select name="cat"><option>All</option>${[...new Set(PRESETS.map(p=>p.cat))].map(c=>`<option>${esc(c)}</option>`).join('')}</select></div><div class="form-actions field full"><button class="primary-btn">Find items</button></div></form><div id="fitsResults"></div>`,m=>{$('#fitsForm',m).onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target)),w=toCm(d.w,u),h=toCm(d.h,u);let list=PRESETS.filter(p=>p.id!=='custom'&&((p.w<=w&&p.h<=h)||(p.h<=w&&p.w<=h)));if(d.cat!=='All')list=list.filter(p=>p.cat===d.cat);$('#fitsResults',m).innerHTML=`<div class="section-mini"><b>${list.length} objects fit</b><span>including 90° rotation</span></div><div class="option-grid">${list.slice(0,24).map(objectCard).join('')}</div>`;$$('[data-preset]',$('#fitsResults',m)).forEach(b=>b.onclick=()=>{const p=PRESETS.find(x=>x.id===b.dataset.preset);addPreset(p);m.remove()})}})}
function fitThroughDoor(){const o=objects().find(x=>x.id===state.selectedId);if(!o)return toast('Select the furniture first');const doors=objects().filter(x=>x.type==='door');if(!doors.length)return toast('Add a door first');const max=Math.max(...doors.map(d=>Math.max(d.w,d.h))),minSide=Math.min(o.w,o.h);toast(minSide<=max?`Likely fits: ${display(minSide,rUnit())} side vs ${display(max,rUnit())} widest door`:`Too wide: smallest side is ${display(minSide,rUnit())}`)}
function compareLayoutsModal(){const r=currentRoom();if(!r)return;modal('Compare layouts',`<div class="compare-list">${r.layouts.map(l=>{const m=layoutMetrics(l);return `<div class="compare-card"><div><b>${esc(l.name)}</b><span>${m.items} items</span></div><div><b>${m.score}</b><span>Fit score</span></div><div><b>${m.occupied.toFixed(1)}%</b><span>Footprint</span></div><div><b>${m.issues}</b><span>Issues</span></div></div>`}).join('')}</div><p class="help">Use the comparison to spot layouts with fewer conflicts and more open floor area.</p>`)}
function shoppingListModal(){const list=objects().filter(o=>o.owned===false);const total=list.reduce((s,o)=>s+(o.price||0),0);modal('Shopping list',list.length?`<div class="list">${list.map(o=>`<div class="list-row"><span><b>${esc(o.name)}</b><span class="meta">${display(o.w,rUnit())} × ${display(o.h,rUnit())}</span></span><span>${o.price?Number(o.price).toLocaleString():''}</span></div>`).join('')}</div><div class="notice">Estimated saved item total: <b>${total.toLocaleString()}</b></div><div class="form-actions"><button class="secondary-btn" id="copyShopping">Copy list</button><button class="secondary-btn" id="csvShopping">Export CSV</button></div>`:`<div class="empty-state"><div class="big">🛒</div><h3>Nothing to buy yet</h3><p>Edit an object and mark it “Considering / To buy”.</p></div>`,m=>{$('#copyShopping',m)?.addEventListener('click',()=>copyText(list.map(o=>`• ${o.name} — ${display(o.w,rUnit())} × ${display(o.h,rUnit())}${o.price?` — ${o.price}`:''}`).join('\n')));$('#csvShopping',m)?.addEventListener('click',()=>downloadCSV([['Item','Width cm','Depth cm','Price','Notes'],...list.map(o=>[o.name,o.w,o.h,o.price||'',o.notes||''])],`${slug(currentRoom().name)}-shopping-list.csv`))})}
function remeasureModal(){const list=objects().filter(o=>o.measureConfidence!=='exact');modal('Measurements to confirm',list.length?`<div class="list">${list.map(o=>`<button class="list-row" data-id="${o.id}"><span><b>${esc(o.name)}</b><span class="meta">${o.measureConfidence==='remeasure'?'Needs re-measuring':'Approximate'} • ${display(o.w,rUnit())} × ${display(o.h,rUnit())}</span></span><span>›</span></button>`).join('')}</div>`:`<div class="empty-state"><div class="big">📐</div><h3>All measurements are exact</h3><p>No items are marked approximate or needing re-measurement.</p></div>`,m=>$$('[data-id]',m).forEach(b=>b.onclick=()=>{m.remove();editObjectModal(b.dataset.id)}))}
function objectListModal(){const arr=objects();modal('Objects in this layout',arr.length?`<div class="field"><input id="objListSearch" placeholder="Search objects…"></div><div class="list" id="objListRows"></div>`:`<div class="empty-state"><div class="big">🪑</div><h3>No objects yet</h3></div>`,m=>{const draw=()=>{const q=$('#objListSearch',m)?.value.toLowerCase()||'';$('#objListRows',m).innerHTML=arr.filter(o=>o.name.toLowerCase().includes(q)).map(o=>`<div class="list-row"><button class="plain-select" data-select="${o.id}"><b>${esc(o.name)}</b><span class="meta">${o.type} • ${display(o.w,rUnit())} × ${display(o.h,rUnit())}</span></button><div class="row-actions"><button class="tiny-btn" data-hide="${o.id}">${o.hidden?'👁':'🙈'}</button><button class="tiny-btn" data-lock="${o.id}">${o.locked?'🔒':'🔓'}</button></div></div>`).join('');$$('[data-select]',m).forEach(b=>b.onclick=()=>{state.selectedId=b.dataset.select;m.remove();renderPlan()});$$('[data-hide]',m).forEach(b=>b.onclick=()=>{const o=arr.find(x=>x.id===b.dataset.hide);o.hidden=!o.hidden;persist();draw();renderPlan(true)});$$('[data-lock]',m).forEach(b=>b.onclick=()=>{const o=arr.find(x=>x.id===b.dataset.lock);o.locked=!o.locked;persist();draw();renderPlan()})};$('#objListSearch',m)?.addEventListener('input',draw);draw()})}

function selectedToolsModal(id){const o=objects().find(x=>x.id===id);if(!o)return;modal(`${o.name} tools`,`<div class="tool-grid"><button data-t="fit">✨<b>Find open spot</b><span>Where can this fit?</span></button><button data-t="center">⊙<b>Center in room</b><span>Quick placement</span></button><button data-t="wall">🧲<b>Nearest wall</b><span>Snap to closest edge</span></button><button data-t="alignX">↔️<b>Center horizontally</b><span>Room centerline</span></button><button data-t="alignY">↕️<b>Center vertically</b><span>Room centerline</span></button><button data-t="state">🛋️<b>Toggle open state</b><span>${o.altW&&o.altH?'Preview alternate footprint':'Set alternate size in Edit'}</span></button><button data-t="save">💾<b>Save to My Objects</b><span>Reuse measurements</span></button><button data-t="front">⬆️<b>Bring to front</b><span>Layer order</span></button><button data-t="back">⬇️<b>Send to back</b><span>Layer order</span></button></div><div class="nudge-panel"><span>Nudge</span><div><button data-n="0,-1">↑</button><button data-n="-1,0">←</button><button data-n="1,0">→</button><button data-n="0,1">↓</button></div></div>`,m=>{$$('[data-t]',m).forEach(b=>b.onclick=()=>{const t=b.dataset.t;if(t==='fit'){m.remove();whereCanFitSelected();return}snapshot();const r=currentRoom();if(t==='center'){o.x=r.width/2-o.w/2;o.y=r.height/2-o.h/2}else if(t==='wall'){const ds=[{v:o.x,a:'l'},{v:r.width-(o.x+o.w),a:'r'},{v:o.y,a:'t'},{v:r.height-(o.y+o.h),a:'b'}].sort((a,b)=>a.v-b.v)[0];if(ds.a==='l')o.x=0;if(ds.a==='r')o.x=r.width-o.w;if(ds.a==='t')o.y=0;if(ds.a==='b')o.y=r.height-o.h}else if(t==='alignX')o.x=r.width/2-o.w/2;else if(t==='alignY')o.y=r.height/2-o.h/2;else if(t==='state'){if(o.altW&&o.altH){[o.w,o.altW]=[o.altW,o.w];[o.h,o.altH]=[o.altH,o.h];o.openState=!o.openState;normalizeWithinRoom(o)}else toast('Add an alternate width and depth in Edit first')}else if(t==='save'){const cp=deepClone(o);delete cp.id;delete cp.x;delete cp.y;cp.icon='⬜';state.library.unshift(cp);toast('Saved to My Objects')}else if(t==='front'){const i=objects().indexOf(o);objects().splice(i,1);objects().push(o)}else if(t==='back'){const i=objects().indexOf(o);objects().splice(i,1);objects().unshift(o)}persist();m.remove();renderPlan(true)});$$('[data-n]',m).forEach(b=>b.onclick=()=>{const [dx,dy]=b.dataset.n.split(',').map(Number),step=state.settings.snap?state.settings.snapSize:1;snapshot();o.x+=dx*step;o.y+=dy*step;normalizeWithinRoom(o);persist();renderPlan(true);haptic(5)})})}

function layoutsModal(){const r=currentRoom();if(!r)return toast('Create a room first');modal('Layouts',`<div class="list">${r.layouts.map(l=>{const m=layoutMetrics(l);return `<div class="list-row"><div><b>${esc(l.name)} ${l.favorite?'⭐':''}</b><div class="meta">${l.objects.length} items • score ${m.score} ${l.id===state.currentLayoutId?'• Current':''}</div></div><div class="row-actions"><button class="tiny-btn" data-open="${l.id}">Open</button><button class="tiny-btn" data-menu="${l.id}">⋮</button></div></div>`}).join('')}</div><div class="form-actions"><button class="primary-btn" id="duplicateLayout">＋ Duplicate current</button><button class="secondary-btn" id="blankLayout">Blank</button></div><div class="form-actions"><button class="secondary-btn" id="compareLayoutBtn">🅰️🅱️ Compare layouts</button></div>`,m=>{$$('[data-open]',m).forEach(b=>b.onclick=()=>{state.currentLayoutId=b.dataset.open;state.selectedId=null;state.measureDraft=null;persist();m.remove();renderAll()});$$('[data-menu]',m).forEach(b=>b.onclick=()=>layoutMenu(b.dataset.menu,m));$('#duplicateLayout',m).onclick=()=>{const cur=currentLayout();snapshot();const cp=deepClone(cur);cp.id=uid('layout');cp.name=nextLayoutName(r);cp.createdAt=now();cp.updatedAt=now();cp.objects.forEach(o=>o.id=uid('obj'));cp.measurements=(cp.measurements||[]).map(x=>({...x,id:uid('measure')}));r.layouts.push(cp);state.currentLayoutId=cp.id;persist();m.remove();renderAll();toast('Layout duplicated')};$('#blankLayout',m).onclick=()=>{snapshot();const l=newLayout(nextLayoutName(r));r.layouts.push(l);state.currentLayoutId=l.id;persist();m.remove();renderAll();toast('Blank layout added')};$('#compareLayoutBtn',m).onclick=()=>{m.remove();compareLayoutsModal()}})}
