function roomSettingsModal(){const r=currentRoom();if(!r)return;const u=r.unit;modal('Room settings',`<form id="roomSettingsForm" class="form-grid"><div class="field full"><label>Room name</label><input name="name" value="${attr(r.name)}"></div><div class="field"><label>Width (${u})</label><input type="number" step="0.1" name="width" value="${unitInput(r.width,u)}"></div><div class="field"><label>Length (${u})</label><input type="number" step="0.1" name="height" value="${unitInput(r.height,u)}"></div><div class="field"><label>Display unit</label><select name="unit">${Object.keys(UNIT).map(k=>`<option ${k===u?'selected':''}>${k}</option>`).join('')}</select></div><div class="field"><label>Room type</label><input name="roomType" value="${attr(r.roomType||'Room')}"></div><div class="field full"><label>Room notes</label><textarea name="notes" rows="4">${esc(r.notes||'')}</textarea></div><div class="form-actions field full"><button type="button" class="secondary-btn cancel">Cancel</button><button class="primary-btn">Save room</button></div></form>`,m=>{$('.cancel',m).onclick=()=>m.remove();$('form',m).onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));snapshot();const oldW=r.width,oldH=r.height,nw=Math.max(100,toCm(d.width,u)),nh=Math.max(100,toCm(d.height,u));r.name=d.name||r.name;r.width=nw;r.height=nh;r.unit=d.unit;r.roomType=d.roomType||r.roomType;r.notes=d.notes;r.updatedAt=now();r.layouts.forEach(l=>l.objects.forEach(o=>{if((o.type==='door'||o.type==='window')&&o.wall){const width=Math.max(o.w,o.h),oldOff=(o.wall==='top'||o.wall==='bottom')?o.x:o.y;positionWallOpeningForRoom(o,r,o.wall,width,oldOff)}else normalizeWithinRoomForRoom(o,r)}));persist();m.remove();renderAll();toast('Room updated')}})}
function positionWallOpeningForRoom(o,r,wall,width,offset){if(wall==='top'){o.w=width;o.h=o.type==='door'?4:8;o.x=clamp(offset,0,r.width-width);o.y=-o.h/2}else if(wall==='bottom'){o.w=width;o.h=o.type==='door'?4:8;o.x=clamp(offset,0,r.width-width);o.y=r.height-o.h/2}else if(wall==='left'){o.w=o.type==='door'?4:8;o.h=width;o.x=-o.w/2;o.y=clamp(offset,0,r.height-width)}else{o.w=o.type==='door'?4:8;o.h=width;o.x=r.width-o.w/2;o.y=clamp(offset,0,r.height-width)}o.rotation=0}
