function applyWorkspaceMode(mode){
  state.settings.workspaceMode=mode;
  if(mode==='clean')Object.assign(state.settings,{grid:false,labels:false,dimensions:false,clearances:false,measurements:false,zones:false});
  else if(mode==='precision')Object.assign(state.settings,{grid:true,labels:true,dimensions:true,clearances:true,measurements:true,zones:true});
  else Object.assign(state.settings,{grid:true,labels:true,dimensions:true,clearances:true,measurements:true,zones:true});
  persist();renderPlan(true);applyAppearance();
}
